import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"依赖与制品体积审计","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dependency-audit.md","filePath":"zh/dependency-audit.md","lastUpdated":1785233987000}`),a={name:`zh/dependency-audit.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="依赖与制品体积审计" tabindex="-1">依赖与制品体积审计 <a class="header-anchor" href="#依赖与制品体积审计" aria-label="Permalink to “依赖与制品体积审计”">​</a></h1><p>发布策略要求每一组重复 Rust 依赖和本地 crate override 都有明确决策，并为三种可执行交付面 设置体积预算。机器可读的唯一事实来源是 <a href="../../audits/release-policy.json"><code>audits/release-policy.json</code></a>。</p><h2 id="重复依赖决策" tabindex="-1">重复依赖决策 <a class="header-anchor" href="#重复依赖决策" aria-label="Permalink to “重复依赖决策”">​</a></h2><p>2026-07-28 的审计记录了五组重复依赖：</p><table tabindex="0"><thead><tr><th>依赖</th><th>版本</th><th>决策</th><th>替换条件</th></tr></thead><tbody><tr><td><code>brotli</code></td><td>7.0.0 / 8.0.4</td><td>保留</td><td>移除 patched WOFF2 decoder 链时一并移除 v7。</td></tr><tr><td><code>brotli-decompressor</code></td><td>4.0.3 / 5.0.3</td><td>保留</td><td>随 Brotli v7 一并移除 v4。</td></tr><tr><td><code>thiserror</code></td><td>1.0.69 / 2.0.18</td><td>保留</td><td>移除两个 WOFF2 compatibility crate 时移除 v1。</td></tr><tr><td><code>thiserror-impl</code></td><td>1.0.69 / 2.0.18</td><td>保留</td><td>跟随已审计的 <code>thiserror</code> 版本。</td></tr><tr><td><code>unicode-width</code></td><td>0.1.14 / 0.2.2</td><td>保留</td><td>等待 <code>miette</code>/<code>textwrap</code> 在不改变诊断输出的前提下统一版本。</td></tr></tbody></table><p>所有决策均由 fontmin-rs maintainers 负责。新增重复项、已记录版本变化，或重复项消失但保留 决策未删除，都会使依赖门禁失败。</p><h2 id="vendored-patch-决策" tabindex="-1">Vendored patch 决策 <a class="header-anchor" href="#vendored-patch-决策" aria-label="Permalink to “Vendored patch 决策”">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>上游</th><th>决策与退出条件</th></tr></thead><tbody><tr><td><code>allsorts</code> 0.17.0</td><td><a href="https://github.com/yeslogic/allsorts" target="_blank" rel="noreferrer">yeslogic/allsorts</a></td><td>保留 CFF INDEX 与 <code>endchar</code> 修正；上游版本具备等价行为且永久回归语料通过后移除。</td></tr><tr><td><code>safer-bytes</code> 0.2.0</td><td><a href="https://github.com/danieleades/safer-bytes" target="_blank" rel="noreferrer">danieleades/safer-bytes</a></td><td>保留 stable-Rust compatibility copy，直到选定的 WOFF2 decoder 不再依赖它。</td></tr><tr><td><code>woff2-patched</code> 0.4.0</td><td><a href="https://github.com/zimond/woff2-rs" target="_blank" rel="noreferrer">zimond/woff2-rs</a></td><td>保留显式坐标 wrapping；上游版本或自有 decoder 通过全部 WOFF2 回归后替换。</td></tr></tbody></table><p>每个 override 的源码旁都有 patch notes。审计会同时验证 root Cargo patch、说明、负责人、 上游地址、决策与移除条件。</p><h2 id="release-制品体积预算" tabindex="-1">Release 制品体积预算 <a class="header-anchor" href="#release-制品体积预算" aria-label="Permalink to “Release 制品体积预算”">​</a></h2><p>Release build 启用 thin LTO、单 codegen unit 与符号裁剪。预算为受支持 CI 平台保留余量：</p><table tabindex="0"><thead><tr><th>制品</th><th style="text-align:right;">预算</th></tr></thead><tbody><tr><td>Rust CLI</td><td style="text-align:right;">8 MiB</td></tr><tr><td>Native Node binding</td><td style="text-align:right;">8 MiB</td></tr><tr><td>Browser WASM binary</td><td style="text-align:right;">4 MiB</td></tr></tbody></table><p>启用 release profile 后，macOS arm64 本地实测为：CLI 4,425,520 bytes、native binding 3,279,968 bytes、WASM 2,964,395 bytes。CI 会把平台实测写入 <code>audits/artifact-current.json</code>，并与性能报告一起上传。</p><p>只检查依赖决策：</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit:dependencies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>构建并测量全部 release 交付面：</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit:artifacts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>体积超限时仍会先持久化完整报告，便于直接定位对应交付面和实际字节数。</p>`,18)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};